async function handleResource(req: Request, pathname: string): Promise<Response | null> {
  for (const action of ACTIONS) {
    const base = action.path.replace(/\/:id$/, "");
    const isItem = pathname.startsWith(base + "/") && action.path.includes(":id");
    const isCollection = pathname === action.path || pathname === base;
    if (!isItem && !isCollection && pathname !== action.path) continue;
    if (req.method !== action.http_method) continue;
    const table = action.path.split("/")[2];
    if (action.http_method === "GET" && !action.path.includes(":id")) {
      const rows = db.query(`SELECT id, data FROM ${table} ORDER BY created_at DESC`).all() as any[];
      return json(rows.map((r) => ({ id: r.id, ...JSON.parse(r.data) })));
    }
    if (action.http_method === "GET" && isItem) {
      const id = pathname.slice(base.length + 1);
      const row = db.query(`SELECT id, data FROM ${table} WHERE id = ?`).get(id) as any;
      if (!row) return json({ error: "not found" }, 404);
      return json({ id: row.id, ...JSON.parse(row.data) });
    }
    if (action.http_method === "POST") {
      const body = await req.json();
      const id = body.id || crypto.randomUUID();
      const { id: _i, ...rest } = body;
      db.query(`INSERT INTO ${table} (id, data) VALUES (?, ?)`).run(id, JSON.stringify(rest));
      return json({ id, ...rest }, 201);
    }
    if (action.http_method === "PUT" && isItem) {
      const id = pathname.slice(base.length + 1);
      const body = await req.json();
      db.query(`UPDATE ${table} SET data = ?, updated_at = datetime('now') WHERE id = ?`).run(JSON.stringify(body), id);
      return json({ id, ...body });
    }
    if (action.http_method === "DELETE" && isItem) {
      const id = pathname.slice(base.length + 1);
      db.query(`DELETE FROM ${table} WHERE id = ?`).run(id);
      return json({ ok: true });
    }
  }
  return null;
}

